import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"English Diagnostic | Find a Retestable Baseline","description":"Start with one five-minute English baseline, then complete a four-skill diagnostic and fourteen-day retest when your goal calls for it.","frontmatter":{"title":"English Diagnostic | Find a Retestable Baseline","description":"Start with one five-minute English baseline, then complete a four-skill diagnostic and fourteen-day retest when your goal calls for it.","updated":"2026-10-19T00:00:00.000Z","topic":"english-learning","intent":"diagnostic","schema":"Article","socialImage":"/assets/social/english-en.png","socialImageAlt":"English diagnostic and retest hub sharing image"},"headers":[],"relativePath":"en/topics/english-diagnostic.md","filePath":"en/topics/english-diagnostic.md","lastUpdated":1792368000000}'),s={name:"en/topics/english-diagnostic.md"};function o(r,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="english-diagnostic-find-a-retestable-baseline" tabindex="-1">English Diagnostic: Find a Retestable Baseline <a class="header-anchor" href="#english-diagnostic-find-a-retestable-baseline" aria-label="Permalink to &quot;English Diagnostic: Find a Retestable Baseline&quot;">​</a></h1><p>If you are looking for an English level test, CEFR self-assessment, or workplace English plan, turn the abstract idea of “level” into evidence you can keep. A diagnostic is not a label; it is the next barrier worth repairing.</p><h2 id="who-it-is-for" tabindex="-1">Who It Is For <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who It Is For&quot;">​</a></h2><ul><li>People who want to see where listening, speaking, reading, and writing each get stuck.</li><li>People who need English for remote collaboration, interviews, technical documentation, or customer conversations.</li><li>Learners who have tried vocabulary lists or tests but cannot tell whether real work has improved.</li></ul><h2 id="keep-one-baseline-in-five-minutes" tabindex="-1">Keep One Baseline in Five Minutes <a class="header-anchor" href="#keep-one-baseline-in-five-minutes" aria-label="Permalink to &quot;Keep One Baseline in Five Minutes&quot;">​</a></h2><p>This checks one skill. It is not a CEFR placement or a full listening, speaking, reading, and writing diagnostic. Choose a topic you will use soon, set a five-minute timer, and complete one task:</p><table tabindex="0"><thead><tr><th>Choose</th><th>Five-minute task</th><th>Evidence to keep</th></tr></thead><tbody><tr><td>Listening</td><td>Listen once to a 60–90 second clip</td><td>Write its gist and one detail you heard</td></tr><tr><td>Reading</td><td>Read about 150–250 words</td><td>Write one claim and one piece of supporting evidence</td></tr><tr><td>Speaking</td><td>Record a 60-second explanation without notes</td><td>Keep the raw recording and mark one pause or unclear point</td></tr><tr><td>Writing</td><td>Spend five minutes on a real work or life message</td><td>Keep the draft and mark one uncertain phrase or fact</td></tr></tbody></table><p>Do not polish it with AI first. Name one specific barrier, such as connected speech, finding evidence, losing your train of thought, or leaving the reader unsure what happens next. Keep the sample privately, practise one barrier, and retest with a similar but different topic after fourteen days.</p><h2 id="full-diagnostic" tabindex="-1">Full Diagnostic <a class="header-anchor" href="#full-diagnostic" aria-label="Permalink to &quot;Full Diagnostic&quot;">​</a></h2><p>Use the complete diagnostic when you need to locate barriers across all four skills. It takes substantially longer than five minutes: the worksheet suggests 2–4 minutes of audio, 600–1,000 words of reading, a two-minute spoken sample, and a 20-minute writing task, followed by comparison of conditions, errors, and transfer. Copy the <a href="./../templates/english-diagnostic">English Diagnostic worksheet</a>; do not infer an overall level from one sample.</p><h2 id="continue-in-three-steps" tabindex="-1">Continue in Three Steps <a class="header-anchor" href="#continue-in-three-steps" aria-label="Permalink to &quot;Continue in Three Steps&quot;">​</a></h2><ol><li>Read <a href="./../threads/part-1/0-cefr">CEFR Goals and Self-check</a> and choose a real topic you will use soon.</li><li>For a full diagnostic, keep all four first samples with the <a href="./../templates/english-diagnostic">English Diagnostic</a>, then use the <a href="./../templates/listening-audit">Listening Evidence Card</a>, <a href="./../templates/speaking-evidence">Speaking Evidence Card</a>, <a href="./../templates/reading-evidence">Reading Evidence Card</a>, or <a href="./../templates/writing-evidence">Writing Evidence Card</a> as needed.</li><li>Name one smallest barrier, practise for fourteen days, and retest with different material or a different conversation partner. Put the visible change into the <a href="./../templates/evidence-chain">Evidence Chain</a>.</li></ol><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Do not turn the diagnostic into a one-time exam. Keep an unaided sample first, then use AI to explain errors, create practice, or simulate a conversation. You confirm meaning and transfer yourself. After the first diagnostic, continue to <a href="./../recent-updates">Recent Updates</a> or the <a href="./ai-learning-workflows">AI Learning Workflow Hub</a>.</p>',14)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
